{
  "name": "interview-scheduler",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "test": "vitest run"
  },
  "engines": {
    "node": ">=20.11"
  }
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  test: {
    environment: "node",
    include: ["src/**/*.test.js"],
  },
  server: {
    port: 5173,
    strictPort: true,
  },
});

/** Provided availability for the recruiter scheduling UI. */

export const WEEK_LABEL = "Week of Sep 7–11, 2026";

export const WEEK_DATES = {
  Mon: "Sep 7",
  Tue: "Sep 8",
  Wed: "Sep 9",
  Thu: "Sep 10",
  Fri: "Sep 11",
};

export const ENGINEERS = [
  {
    id: "alex",
    name: "Alex Rivera",
    role: "Backend",
    color: "#215e75",
    availability: [
      { day: "Mon", start: "09:00", end: "12:00" },
      { day: "Wed", start: "09:00", end: "12:00" },
      { day: "Fri", start: "14:00", end: "18:00" },
    ],
  },
  {
    id: "priya",
    name: "Priya Shah",
    role: "Frontend",
    color: "#c05621",
    availability: [
      { day: "Mon", start: "13:00", end: "18:00" },
      { day: "Tue", start: "09:00", end: "12:00" },
      { day: "Tue", start: "14:00", end: "16:00" },
      { day: "Thu", start: "10:00", end: "16:00" },
    ],
  },
  {
    id: "sam",
    name: "Sam Okonkwo",
    role: "Staff engineer",
    color: "#4a5080",
    availability: [
      { day: "Tue", start: "13:00", end: "18:00" },
      { day: "Wed", start: "14:00", end: "18:00" },
      { day: "Thu", start: "09:00", end: "12:00" },
      { day: "Fri", start: "09:00", end: "12:00" },
    ],
  },
];

export const CANDIDATES = [
  {
    id: "jordan",
    name: "Jordan Hale",
    role: "Senior frontend",
    preferred: { day: "Tue", start: "14:00", end: "17:00" },
  },
  {
    id: "maya",
    name: "Maya Chen",
    role: "Backend",
    preferred: { day: "Mon", start: "09:00", end: "12:00" },
  },
  {
    id: "chris",
    name: "Chris Patel",
    role: "Full-stack",
    preferred: { day: "Thu", start: "10:00", end: "15:00" },
  },
  {
    id: "riley",
    name: "Riley Brooks",
    role: "Mobile",
    preferred: { day: "Fri", start: "14:00", end: "18:00" },
  },
];

export const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri"];

export const DAY_LABELS = {
  Mon: "Monday",
  Tue: "Tuesday",
  Wed: "Wednesday",
  Thu: "Thursday",
  Fri: "Friday",
};

export const DAY_START_MINUTES = 9 * 60;
export const DAY_END_MINUTES = 18 * 60;
export const SLOT_MINUTES = 30;

export function timeToMinutes(time) {
  const [hours, minutes] = String(time).split(":").map(Number);
  if (!Number.isInteger(hours) || !Number.isInteger(minutes)) {
    throw new Error(`Invalid time '${time}'. Expected HH:MM.`);
  }
  return hours * 60 + minutes;
}

export function minutesToTime(totalMinutes) {
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

export function formatTime12(timeOrMinutes) {
  const minutes =
    typeof timeOrMinutes === "number" ? timeOrMinutes : timeToMinutes(timeOrMinutes);
  const hour24 = Math.floor(minutes / 60);
  const minute = minutes % 60;
  const period = hour24 >= 12 ? "PM" : "AM";
  const hour12 = hour24 % 12 || 12;
  return `${hour12}:${String(minute).padStart(2, "0")} ${period}`;
}

export function formatRange12(start, end) {
  return `${formatTime12(start)}–${formatTime12(end)}`;
}

export function buildTimeSlots() {
  const slots = [];
  for (let start = DAY_START_MINUTES; start < DAY_END_MINUTES; start += SLOT_MINUTES) {
    slots.push({
      start,
      end: start + SLOT_MINUTES,
      startTime: minutesToTime(start),
      endTime: minutesToTime(start + SLOT_MINUTES),
    });
  }
  return slots;
}

export function isRangeCoveringSlot(range, day, startMinutes) {
  if (!range || range.day !== day) {
    return false;
  }
  const from = timeToMinutes(range.start);
  const to = timeToMinutes(range.end);
  return startMinutes >= from && startMinutes + SLOT_MINUTES <= to;
}

export function engineersAvailableAt(engineers, day, startMinutes) {
  return engineers.filter((engineer) =>
    engineer.availability.some((range) => isRangeCoveringSlot(range, day, startMinutes)),
  );
}

export function getSlotMatch(candidate, engineers, day, startMinutes) {
  const availableEngineers = engineersAvailableAt(engineers, day, startMinutes);
  const candidateAvailable = candidate
    ? isRangeCoveringSlot(candidate.preferred, day, startMinutes)
    : false;

  return {
    availableEngineers,
    candidateAvailable,
    bookable: Boolean(candidate) && candidateAvailable && availableEngineers.length > 0,
  };
}

export function listBookableSlots(candidate, engineers) {
  if (!candidate) {
    return [];
  }

  const bookable = [];
  for (const day of DAYS) {
    for (const slot of buildTimeSlots()) {
      const match = getSlotMatch(candidate, engineers, day, slot.start);
      if (match.bookable) {
        bookable.push({
          day,
          start: slot.start,
          end: slot.end,
          engineers: match.availableEngineers,
        });
      }
    }
  }
  return bookable;
}

export function createInterview({ candidate, engineer, engineers, day, startMinutes }) {
  if (!candidate) {
    throw new Error("Select a candidate before scheduling.");
  }
  if (!engineer) {
    throw new Error("Select an engineer before scheduling.");
  }

  const match = getSlotMatch(candidate, engineers, day, startMinutes);
  if (!match.bookable) {
    throw new Error("That slot is not available for both the candidate and an engineer.");
  }
  if (!match.availableEngineers.some((person) => person.id === engineer.id)) {
    throw new Error(`${engineer.name} is not available at that time.`);
  }

  const endMinutes = startMinutes + SLOT_MINUTES;
  return {
    candidateId: candidate.id,
    candidateName: candidate.name,
    engineerId: engineer.id,
    engineerName: engineer.name,
    day,
    startMinutes,
    endMinutes,
    startTime: minutesToTime(startMinutes),
    endTime: minutesToTime(endMinutes),
    summary: `${engineer.name} will interview ${candidate.name} on ${DAY_LABELS[day]} from ${formatTime12(startMinutes)} to ${formatTime12(endMinutes)}.`,
  };
}

import { describe, expect, it } from "vitest";

import { CANDIDATES, ENGINEERS } from "../data/people.js";
import {
  createInterview,
  formatTime12,
  getSlotMatch,
  isRangeCoveringSlot,
  listBookableSlots,
  timeToMinutes,
} from "./schedule.js";

const jordan = CANDIDATES.find((person) => person.id === "jordan");
const maya = CANDIDATES.find((person) => person.id === "maya");
const priya = ENGINEERS.find((person) => person.id === "priya");
const sam = ENGINEERS.find((person) => person.id === "sam");
const alex = ENGINEERS.find((person) => person.id === "alex");

describe("overlapping interview slots", () => {
  it("treats availability end times as exclusive so a 2–5 PM window is not bookable at 5:00", () => {
    const range = { day: "Tue", start: "14:00", end: "17:00" };

    expect(isRangeCoveringSlot(range, "Tue", timeToMinutes("14:00"))).toBe(true);
    expect(isRangeCoveringSlot(range, "Tue", timeToMinutes("16:30"))).toBe(true);
    expect(isRangeCoveringSlot(range, "Tue", timeToMinutes("17:00"))).toBe(false);
    expect(isRangeCoveringSlot(range, "Mon", timeToMinutes("14:00"))).toBe(false);
  });

  it("only returns 30-minute slots where Jordan and at least one engineer overlap", () => {
    const slots = listBookableSlots(jordan, ENGINEERS);

    expect(slots.every((slot) => slot.day === "Tue")).toBe(true);
    expect(slots.map((slot) => formatTime12(slot.start))).toEqual([
      "2:00 PM",
      "2:30 PM",
      "3:00 PM",
      "3:30 PM",
      "4:00 PM",
      "4:30 PM",
    ]);

    const twoPm = slots.find((slot) => slot.start === timeToMinutes("14:00"));
    const fourPm = slots.find((slot) => slot.start === timeToMinutes("16:00"));

    expect(twoPm.engineers.map((engineer) => engineer.id).sort()).toEqual(["priya", "sam"]);
    expect(fourPm.engineers.map((engineer) => engineer.id)).toEqual(["sam"]);
  });

  it("does not treat engineer-only or candidate-only time as bookable", () => {
    const priyaTuesdayMorning = getSlotMatch(jordan, ENGINEERS, "Tue", timeToMinutes("09:00"));
    expect(priyaTuesdayMorning.availableEngineers.map((engineer) => engineer.id)).toEqual(["priya"]);
    expect(priyaTuesdayMorning.candidateAvailable).toBe(false);
    expect(priyaTuesdayMorning.bookable).toBe(false);

    const jordanWithoutEngineer = getSlotMatch(jordan, [alex], "Tue", timeToMinutes("14:00"));
    expect(jordanWithoutEngineer.candidateAvailable).toBe(true);
    expect(jordanWithoutEngineer.availableEngineers).toEqual([]);
    expect(jordanWithoutEngineer.bookable).toBe(false);
  });

  it("creates a confirmation payload only when the chosen engineer is free", () => {
    const interview = createInterview({
      candidate: jordan,
      engineer: priya,
      engineers: ENGINEERS,
      day: "Tue",
      startMinutes: timeToMinutes("14:30"),
    });

    expect(interview.summary).toBe(
      "Priya Shah will interview Jordan Hale on Tuesday from 2:30 PM to 3:00 PM.",
    );
    expect(interview.engineerId).toBe("priya");
    expect(interview.candidateId).toBe("jordan");

    expect(() =>
      createInterview({
        candidate: jordan,
        engineer: alex,
        engineers: ENGINEERS,
        day: "Tue",
        startMinutes: timeToMinutes("14:30"),
      }),
    ).toThrow(/Alex Rivera is not available/);

    expect(() =>
      createInterview({
        candidate: maya,
        engineer: sam,
        engineers: ENGINEERS,
        day: "Mon",
        startMinutes: timeToMinutes("09:00"),
      }),
    ).toThrow(/not available for both the candidate and an engineer/);
  });
});

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import App from "./App.jsx";
import "./styles.css";

createRoot(document.getElementById("root")).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import { useEffect, useMemo, useState } from "react";

import { CANDIDATES, ENGINEERS, WEEK_DATES, WEEK_LABEL } from "./data/people.js";
import {
  DAYS,
  DAY_LABELS,
  buildTimeSlots,
  createInterview,
  formatRange12,
  formatTime12,
  getSlotMatch,
  listBookableSlots,
} from "./lib/schedule.js";

const TIME_SLOTS = buildTimeSlots();

export default function App() {
  const [candidateId, setCandidateId] = useState(CANDIDATES[0].id);
  const [viewMode, setViewMode] = useState("all");
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [engineerId, setEngineerId] = useState(null);
  const [interview, setInterview] = useState(null);
  const [error, setError] = useState("");

  const candidate = CANDIDATES.find((person) => person.id === candidateId) ?? null;
  const bookableSlots = useMemo(
    () => listBookableSlots(candidate, ENGINEERS),
    [candidate],
  );

  const selectedMatch = selectedSlot
    ? getSlotMatch(candidate, ENGINEERS, selectedSlot.day, selectedSlot.start)
    : null;

  useEffect(() => {
    setSelectedSlot(null);
    setEngineerId(null);
    setError("");
  }, [candidateId]);

  useEffect(() => {
    if (!selectedMatch?.bookable) {
      setEngineerId(null);
      return;
    }
    const stillValid = selectedMatch.availableEngineers.some((person) => person.id === engineerId);
    if (!stillValid) {
      setEngineerId(selectedMatch.availableEngineers[0]?.id ?? null);
    }
  }, [selectedMatch, engineerId]);

  function handleSelectSlot(day, start, match) {
    if (!match.bookable) {
      return;
    }
    setError("");
    setSelectedSlot({ day, start });
    setEngineerId(match.availableEngineers[0].id);
  }

  function handleConfirm() {
    const engineer = ENGINEERS.find((person) => person.id === engineerId);
    try {
      const booked = createInterview({
        candidate,
        engineer,
        engineers: ENGINEERS,
        day: selectedSlot.day,
        startMinutes: selectedSlot.start,
      });
      setInterview(booked);
      setError("");
    } catch (err) {
      setError(err.message);
    }
  }

  function isBookedSlot(day, start) {
    return interview?.day === day && interview?.startMinutes === start;
  }

  return (
    <div className="page">
      <header className="topbar">
        <div>
          <p className="eyebrow">Recruiter workspace</p>
          <h1>Interview Desk</h1>
        </div>
        <p className="week">{WEEK_LABEL}</p>
      </header>

      <main className="layout">
        <aside className="sidebar">
          <label className="field">
            <span>Candidate</span>
            <select
              value={candidateId}
              onChange={(event) => setCandidateId(event.target.value)}
            >
              {CANDIDATES.map((person) => (
                <option key={person.id} value={person.id}>
                  {person.name} — {person.role}
                </option>
              ))}
            </select>
          </label>

          <section className="card preference">
            <h2>Preferred window</h2>
            <p className="preference-day">{DAY_LABELS[candidate.preferred.day]}</p>
            <p className="preference-time">
              {formatRange12(candidate.preferred.start, candidate.preferred.end)}
            </p>
            <p className="hint">
              {bookableSlots.length} overlapping slot{bookableSlots.length === 1 ? "" : "s"} with
              at least one engineer.
            </p>
          </section>

          <section className="card">
            <h2>Engineers</h2>
            <ul className="people">
              {ENGINEERS.map((engineer) => (
                <li key={engineer.id}>
                  <span className="swatch" style={{ background: engineer.color }} />
                  <span>
                    <strong>{engineer.name}</strong>
                    <em>{engineer.role}</em>
                  </span>
                </li>
              ))}
            </ul>
          </section>

          <section className="card legend">
            <h2>How to read the grid</h2>
            <ul>
              <li>
                <span className="key key-bookable" />
                Candidate + engineer overlap — click to schedule
              </li>
              <li>
                <span className="key key-engineer" />
                Engineer free, candidate is not
              </li>
              <li>
                <span className="key key-candidate" />
                Candidate free, no engineer
              </li>
            </ul>
          </section>

          <div className="filters" role="group" aria-label="Calendar filter">
            <button
              type="button"
              className={viewMode === "all" ? "active" : ""}
              onClick={() => setViewMode("all")}
            >
              Full week
            </button>
            <button
              type="button"
              className={viewMode === "bookable" ? "active" : ""}
              onClick={() => setViewMode("bookable")}
            >
              Overlaps only
            </button>
          </div>

          {selectedMatch?.bookable ? (
            <section className="card schedule-panel">
              <h2>Schedule interview</h2>
              <p className="when">
                {DAY_LABELS[selectedSlot.day]} {WEEK_DATES[selectedSlot.day]}
                <br />
                {formatTime12(selectedSlot.start)}–{formatTime12(selectedSlot.start + 30)}
              </p>
              <p className="who">
                <strong>{candidate.name}</strong>
              </p>
              <fieldset>
                <legend>Available engineer</legend>
                {selectedMatch.availableEngineers.map((engineer) => (
                  <label key={engineer.id} className="engineer-choice">
                    <input
                      type="radio"
                      name="engineer"
                      value={engineer.id}
                      checked={engineerId === engineer.id}
                      onChange={() => setEngineerId(engineer.id)}
                    />
                    <span className="swatch" style={{ background: engineer.color }} />
                    {engineer.name}
                  </label>
                ))}
              </fieldset>
              {error ? <p className="error">{error}</p> : null}
              <button type="button" className="confirm" onClick={handleConfirm}>
                Confirm interview
              </button>
            </section>
          ) : (
            <p className="prompt">
              Click a highlighted overlap to pick a 30-minute interview.
            </p>
          )}

          {interview ? (
            <section className="card confirmation" role="status">
              <h2>Interview confirmed</h2>
              <p>{interview.summary}</p>
              <dl>
                <div>
                  <dt>Candidate</dt>
                  <dd>{interview.candidateName}</dd>
                </div>
                <div>
                  <dt>Engineer</dt>
                  <dd>{interview.engineerName}</dd>
                </div>
                <div>
                  <dt>Time</dt>
                  <dd>
                    {DAY_LABELS[interview.day]}, {formatTime12(interview.startMinutes)}–
                    {formatTime12(interview.endMinutes)}
                  </dd>
                </div>
              </dl>
            </section>
          ) : null}
        </aside>

        <section className="calendar" aria-label="Weekly availability calendar">
          <div className="grid">
            <div className="corner" />
            {DAYS.map((day) => (
              <div key={day} className="day-head">
                <span>{DAY_LABELS[day]}</span>
                <small>{WEEK_DATES[day]}</small>
              </div>
            ))}

            {TIME_SLOTS.map((slot) => (
              <div key={slot.start} className="slot-row">
                <div className="time-label">
                  {formatTime12(slot.start).replace(" ", "\u00a0")}
                </div>
                {DAYS.map((day) => {
                  const match = getSlotMatch(candidate, ENGINEERS, day, slot.start);
                  const bookable = match.bookable;
                  const booked = isBookedSlot(day, slot.start);
                  const selected =
                    selectedSlot?.day === day && selectedSlot?.start === slot.start;
                  const hidden = viewMode === "bookable" && !bookable && !booked;
                  const engineerOnly =
                    match.availableEngineers.length > 0 && !match.candidateAvailable;
                  const candidateOnly =
                    match.candidateAvailable && match.availableEngineers.length === 0;

                  let className = "slot";
                  if (bookable) className += " slot-bookable";
                  if (engineerOnly) className += " slot-engineer";
                  if (candidateOnly) className += " slot-candidate";
                  if (selected) className += " slot-selected";
                  if (booked) className += " slot-booked";
                  if (hidden) className += " slot-muted";

                  const engineerNames = match.availableEngineers
                    .map((engineer) => engineer.name)
                    .join(", ");
                  const label = bookable
                    ? `${DAY_LABELS[day]} ${formatTime12(slot.start)}, overlap with ${engineerNames}. Schedule interview.`
                    : `${DAY_LABELS[day]} ${formatTime12(slot.start)}, not an overlap.`;

                  return (
                    <button
                      key={`${day}-${slot.start}`}
                      type="button"
                      className={className}
                      disabled={!bookable}
                      aria-label={label}
                      aria-pressed={selected}
                      onClick={() => handleSelectSlot(day, slot.start, match)}
                    >
                      <span className="dots" aria-hidden="true">
                        {match.availableEngineers.map((engineer) => (
                          <span
                            key={engineer.id}
                            className="dot"
                            style={{ background: engineer.color }}
                          />
                        ))}
                      </span>
                      {bookable ? (
                        <span className="slot-caption">
                          {match.availableEngineers.length === 1
                            ? match.availableEngineers[0].name.split(" ")[0]
                            : `${match.availableEngineers.length} eng`}
                        </span>
                      ) : null}
                      {booked ? <span className="slot-caption">Booked</span> : null}
                    </button>
                  );
                })}
              </div>
            ))}
          </div>
        </section>
      </main>
    </div>
  );
}

:root {
  --bg: #efe8db;
  --panel: #fbf7ef;
  --ink: #1c1712;
  --muted: #6d6458;
  --line: #ddd4c4;
  --bookable: #1b6b43;
  --bookable-bg: #d7efe2;
  --candidate: #c05621;
  --candidate-bg: #f8e4d4;
  color: var(--ink);
  font-family: "IBM Plex Sans", "Segoe UI", sans-serif;
  background: var(--bg);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  min-height: 100%;
}

body {
  background:
    radial-gradient(circle at 12% 8%, #f7f1e5 0, transparent 36%),
    var(--bg);
}

button,
select,
input {
  font: inherit;
}

.page {
  max-width: 1280px;
  margin: 0 auto;
  padding: 28px 28px 48px;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 24px;
  margin-bottom: 24px;
}

.eyebrow {
  margin: 0 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 11px;
  color: var(--muted);
}

h1 {
  margin: 0;
  font-family: Fraunces, Georgia, serif;
  font-size: 42px;
  font-weight: 560;
  letter-spacing: -0.03em;
}

.week {
  margin: 0;
  color: var(--muted);
}

.layout {
  display: grid;
  grid-template-columns: 320px minmax(0, 1fr);
  gap: 20px;
  align-items: start;
}

.sidebar,
.calendar,
.card {
  background: var(--panel);
  border: 1px solid var(--line);
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
}

.calendar {
  padding: 12px;
  overflow: auto;
}

.field {
  display: grid;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
}

.field select {
  width: 100%;
  border: 1px solid var(--line);
  background: #fff;
  padding: 10px 12px;
  color: var(--ink);
}

.card {
  padding: 14px;
}

.card h2 {
  margin: 0 0 10px;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}

.preference-day {
  margin: 0;
  font-family: Fraunces, Georgia, serif;
  font-size: 28px;
}

.preference-time {
  margin: 2px 0 8px;
  font-size: 18px;
}

.hint,
.prompt {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
}

.people {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}

.people li,
.engineer-choice {
  display: flex;
  align-items: center;
  gap: 10px;
}

.people strong {
  display: block;
  font-size: 14px;
}

.people em {
  display: block;
  font-style: normal;
  color: var(--muted);
  font-size: 12px;
}

.swatch,
.dot,
.key {
  width: 10px;
  height: 10px;
  border-radius: 99px;
  flex: none;
}

.legend ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
  font-size: 13px;
  color: var(--muted);
