input.contents:
export type Day = "Mon" | "Tue" | "Wed" | "Thu" | "Fri";
export type DurationMinutes = 15 | 30 | 60;

export type TimeRange = {
  day: Day;
  start: string;
  end: string;
};

export type Engineer = {
  id: string;
  name: string;
  role: string;
  email: string;
  image: string;
  color: string;
  availability: TimeRange[];
};

export type Candidate = {
  id: string;
  name: string;
  role: string;
  email: string;
  image: string;
  preferred: TimeRange;
};

export type Interview = {
  id: string;
  candidateId: string;
  candidateName: string;
  engineerId: string;
  engineerName: string;
  day: Day;
  startMinutes: number;
  endMinutes: number;
  durationMinutes: DurationMinutes;
  summary: string;
};

export type TimeSlot = {
  start: number;
  end: number;
  startTime: string;
  endTime: string;
};

export type SlotMatch = {
  availableEngineers: Engineer[];
  busyEngineers: Engineer[];
  candidateAvailable: boolean;
  candidateLocked: boolean;
  bookable: boolean;
  locked: boolean;
};

import type { Day } from "../types";

export const WEEK_LABEL = "Week of Sep 7–11, 2026";

export const WEEK_DATES: Record<Day, string> = {
  Mon: "Sep 7",
  Tue: "Sep 8",
  Wed: "Sep 9",
  Thu: "Sep 10",
  Fri: "Sep 11",
};

export const ENGINEER_USER_IDS = [1, 2, 3] as const;
export const CANDIDATE_USER_IDS = [4, 5, 6, 7] as const;

export const ENGINEER_COLORS = ["#215e75", "#c05621", "#4a5080"] as const;

import type {
  Candidate,
  Day,
  DurationMinutes,
  Engineer,
  Interview,
  SlotMatch,
  TimeRange,
  TimeSlot,
} from "../types";

export const DAYS: Day[] = ["Mon", "Tue", "Wed", "Thu", "Fri"];

export const DAY_LABELS: Record<Day, string> = {
  Mon: "Monday",
  Tue: "Tuesday",
  Wed: "Wednesday",
  Thu: "Thursday",
  Fri: "Friday",
};

export const DAY_START_MINUTES = 9 * 60;
export const DAY_END_MINUTES = 18 * 60;
export const DURATIONS: DurationMinutes[] = [15, 30, 60];

export function timeToMinutes(time: string): number {
  const [hours, minutes] = time.split(":").map(Number);
  if (!Number.isInteger(hours) || !Number.isInteger(minutes)) {
    throw new Error(`Invalid time '${time}'. Expected HH:MM.`);
  }
  return hours * 60 + minutes;
}

export function minutesToTime(totalMinutes: number): string {
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

export function formatTime12(timeOrMinutes: string | number): string {
  const minutes =
    typeof timeOrMinutes === "number" ? timeOrMinutes : timeToMinutes(timeOrMinutes);
  const hour24 = Math.floor(minutes / 60);
  const minute = minutes % 60;
  const period = hour24 >= 12 ? "PM" : "AM";
  const hour12 = hour24 % 12 || 12;
  return `${hour12}:${String(minute).padStart(2, "0")} ${period}`;
}

export function formatRange12(start: string | number, end: string | number): string {
  return `${formatTime12(start)}–${formatTime12(end)}`;
}

export function buildTimeSlots(durationMinutes: DurationMinutes): TimeSlot[] {
  const slots: TimeSlot[] = [];
  for (let start = DAY_START_MINUTES; start + durationMinutes <= DAY_END_MINUTES; start += durationMinutes) {
    slots.push({
      start,
      end: start + durationMinutes,
      startTime: minutesToTime(start),
      endTime: minutesToTime(start + durationMinutes),
    });
  }
  return slots;
}

export function intervalsOverlap(startA: number, endA: number, startB: number, endB: number): boolean {
  return startA < endB && startB < endA;
}

export function isRangeCoveringInterval(
  range: TimeRange,
  day: Day,
  startMinutes: number,
  durationMinutes: number,
): boolean {
  if (range.day !== day) {
    return false;
  }
  const from = timeToMinutes(range.start);
  const to = timeToMinutes(range.end);
  return startMinutes >= from && startMinutes + durationMinutes <= to;
}

export function hasOverlappingBooking(
  bookings: Interview[],
  day: Day,
  startMinutes: number,
  endMinutes: number,
  predicate: (booking: Interview) => boolean,
): boolean {
  return bookings.some(
    (booking) =>
      booking.day === day &&
      intervalsOverlap(startMinutes, endMinutes, booking.startMinutes, booking.endMinutes) &&
      predicate(booking),
  );
}

export function getSlotMatch({
  candidate,
  engineers,
  day,
  startMinutes,
  durationMinutes,
  bookings = [],
}: {
  candidate: Candidate | null;
  engineers: Engineer[];
  day: Day;
  startMinutes: number;
  durationMinutes: DurationMinutes;
  bookings?: Interview[];
}): SlotMatch {
  const endMinutes = startMinutes + durationMinutes;

  const covering = engineers.filter((engineer) =>
    engineer.availability.some((range) =>
      isRangeCoveringInterval(range, day, startMinutes, durationMinutes),
    ),
  );

  const availableEngineers = covering.filter(
    (engineer) =>
      !hasOverlappingBooking(
        bookings,
        day,
        startMinutes,
        endMinutes,
        (booking) => booking.engineerId === engineer.id,
      ),
  );

  const busyEngineers = covering.filter(
    (engineer) => !availableEngineers.some((open) => open.id === engineer.id),
  );

  const coversPreferred = candidate
    ? isRangeCoveringInterval(candidate.preferred, day, startMinutes, durationMinutes)
    : false;

  const candidateLocked = candidate
    ? hasOverlappingBooking(
        bookings,
        day,
        startMinutes,
        endMinutes,
        (booking) => booking.candidateId === candidate.id,
      )
    : false;

  const candidateAvailable = coversPreferred && !candidateLocked;
  const locked = candidateLocked || (coversPreferred && availableEngineers.length === 0 && busyEngineers.length > 0);

  return {
    availableEngineers,
    busyEngineers,
    candidateAvailable: coversPreferred,
    candidateLocked,
    bookable: Boolean(candidate) && candidateAvailable && availableEngineers.length > 0,
    locked,
  };
}

export function listBookableSlots({
  candidate,
  engineers,
  durationMinutes,
  bookings = [],
}: {
  candidate: Candidate | null;
  engineers: Engineer[];
  durationMinutes: DurationMinutes;
  bookings?: Interview[];
}) {
  if (!candidate) {
    return [];
  }

  const bookable = [];
  for (const day of DAYS) {
    for (const slot of buildTimeSlots(durationMinutes)) {
      const match = getSlotMatch({
        candidate,
        engineers,
        day,
        startMinutes: slot.start,
        durationMinutes,
        bookings,
      });
      if (match.bookable) {
        bookable.push({
          day,
          start: slot.start,
          end: slot.end,
          engineers: match.availableEngineers,
        });
      }
    }
  }
  return bookable;
}

export function createInterview({
  candidate,
  engineer,
  engineers,
  day,
  startMinutes,
  durationMinutes,
  bookings = [],
}: {
  candidate: Candidate | null;
  engineer: Engineer | null;
  engineers: Engineer[];
  day: Day;
  startMinutes: number;
  durationMinutes: DurationMinutes;
  bookings?: Interview[];
}): Interview {
  if (!candidate) {
    throw new Error("Select a candidate before scheduling.");
  }
  if (!engineer) {
    throw new Error("Select an engineer before scheduling.");
  }

  const match = getSlotMatch({
    candidate,
    engineers,
    day,
    startMinutes,
    durationMinutes,
    bookings,
  });

  if (match.locked) {
    throw new Error("That time slot is locked for this session.");
  }
  if (!match.bookable) {
    throw new Error("That slot is not available for both the candidate and an engineer.");
  }
  if (!match.availableEngineers.some((person) => person.id === engineer.id)) {
    throw new Error(`${engineer.name} is not available at that time.`);
  }

  const endMinutes = startMinutes + durationMinutes;
  return {
    id: `${candidate.id}-${engineer.id}-${day}-${startMinutes}-${durationMinutes}`,
    candidateId: candidate.id,
    candidateName: candidate.name,
    engineerId: engineer.id,
    engineerName: engineer.name,
    day,
    startMinutes,
    endMinutes,
    durationMinutes,
    summary: `${engineer.name} will interview ${candidate.name} on ${DAY_LABELS[day]} from ${formatTime12(startMinutes)} to ${formatTime12(endMinutes)}.`,
  };
}

import { describe, expect, it } from "vitest";

import availability from "../data/availability.json";
import type { Candidate, DurationMinutes, Engineer, TimeRange } from "../types";
import {
  buildTimeSlots,
  createInterview,
  formatTime12,
  getSlotMatch,
  isRangeCoveringInterval,
  listBookableSlots,
  timeToMinutes,
} from "./schedule";

function engineer(id: string, name: string): Engineer {
  return {
    id,
    name,
    role: "Engineer",
    email: `${id}@example.com`,
    image: "",
    color: "#215e75",
    availability: availability.engineers[id as keyof typeof availability.engineers] as TimeRange[],
  };
}

function candidate(id: string, name: string): Candidate {
  return {
    id,
    name,
    role: "Candidate",
    email: `${id}@example.com`,
    image: "",
    preferred: availability.candidates[id as keyof typeof availability.candidates] as TimeRange,
  };
}

const alex = engineer("1", "Alex Rivera");
const priya = engineer("2", "Priya Shah");
const sam = engineer("3", "Sam Okonkwo");
const engineers = [alex, priya, sam];
const jordan = candidate("4", "Jordan Hale");
const maya = candidate("5", "Maya Chen");

function matchAt(
  person: Candidate,
  start: string,
  duration: DurationMinutes,
  day: TimeRange["day"] = "Tue",
  bookings = [],
  pool = engineers,
) {
  return getSlotMatch({
    candidate: person,
    engineers: pool,
    day,
    startMinutes: timeToMinutes(start),
    durationMinutes: duration,
    bookings,
  });
}

describe("availability intersection", () => {
  it("treats range end times as exclusive", () => {
    const range: TimeRange = { day: "Tue", start: "14:00", end: "17:00" };

    expect(isRangeCoveringInterval(range, "Tue", timeToMinutes("14:00"), 30)).toBe(true);
    expect(isRangeCoveringInterval(range, "Tue", timeToMinutes("16:30"), 30)).toBe(true);
    expect(isRangeCoveringInterval(range, "Tue", timeToMinutes("17:00"), 30)).toBe(false);
    expect(isRangeCoveringInterval(range, "Tue", timeToMinutes("16:00"), 60)).toBe(true);
    expect(isRangeCoveringInterval(range, "Tue", timeToMinutes("16:15"), 60)).toBe(false);
    expect(isRangeCoveringInterval(range, "Mon", timeToMinutes("14:00"), 30)).toBe(false);
  });

  it("requires a contiguous block for the selected duration", () => {
    expect(matchAt(jordan, "14:00", 60).bookable).toBe(true);
    expect(matchAt(jordan, "15:00", 60).availableEngineers.map((person) => person.id).sort()).toEqual([
      "2",
      "3",
    ]);
    expect(matchAt(jordan, "16:00", 60).availableEngineers.map((person) => person.id)).toEqual(["3"]);
    expect(matchAt(jordan, "16:00", 60).bookable).toBe(true);
    expect(matchAt(jordan, "17:00", 60).bookable).toBe(false);
  });

  it("does not invent availability across an engineer's midday gap", () => {
    const spanningNoon = getSlotMatch({
      candidate: maya,
      engineers: [alex],
      day: "Mon",
      startMinutes: timeToMinutes("11:30"),
      durationMinutes: 60,
    });
    expect(spanningNoon.bookable).toBe(false);
  });

  it("lists every 30-minute overlap for Jordan, with the correct engineers", () => {
    const slots = listBookableSlots({
      candidate: jordan,
      engineers,
      durationMinutes: 30,
    });

    expect(slots.every((slot) => slot.day === "Tue")).toBe(true);
    expect(slots.map((slot) => formatTime12(slot.start))).toEqual([
      "2:00 PM",
      "2:30 PM",
      "3:00 PM",
      "3:30 PM",
      "4:00 PM",
      "4:30 PM",
    ]);

    const twoPm = slots.find((slot) => slot.start === timeToMinutes("14:00"));
    const fourPm = slots.find((slot) => slot.start === timeToMinutes("16:00"));
    expect(twoPm?.engineers.map((person) => person.id).sort()).toEqual(["2", "3"]);
    expect(fourPm?.engineers.map((person) => person.id)).toEqual(["3"]);
  });

  it("uses 15-minute start times when duration is 15", () => {
    const slots = listBookableSlots({
      candidate: jordan,
      engineers,
      durationMinutes: 15,
    });
    expect(slots).toHaveLength(12);
    expect(slots[0]?.start).toBe(timeToMinutes("14:00"));
    expect(slots.at(-1)?.start).toBe(timeToMinutes("16:45"));
  });

  it("builds fewer grid starts for longer durations", () => {
    expect(buildTimeSlots(15)).toHaveLength(36);
    expect(buildTimeSlots(30)).toHaveLength(18);
    expect(buildTimeSlots(60)).toHaveLength(9);
  });

  it("does not treat engineer-only or candidate-only time as bookable", () => {
    const morning = matchAt(jordan, "09:00", 30);
    expect(morning.availableEngineers.map((person) => person.id)).toEqual(["2"]);
    expect(morning.candidateAvailable).toBe(false);
    expect(morning.bookable).toBe(false);

    const noEngineer = matchAt(jordan, "14:00", 30, "Tue", [], [alex]);
    expect(noEngineer.candidateAvailable).toBe(true);
    expect(noEngineer.availableEngineers).toEqual([]);
    expect(noEngineer.bookable).toBe(false);
  });

  it("limits overlaps to the filtered engineer", () => {
    const onlyPriya = listBookableSlots({
      candidate: jordan,
      engineers: [priya],
      durationMinutes: 30,
    });
    expect(onlyPriya.map((slot) => formatTime12(slot.start))).toEqual([
      "2:00 PM",
      "2:30 PM",
      "3:00 PM",
      "3:30 PM",
    ]);

    const onlyAlex = listBookableSlots({
      candidate: jordan,
      engineers: [alex],
      durationMinutes: 30,
    });
    expect(onlyAlex).toEqual([]);
  });

  it("locks a booked candidate slot for the rest of the session", () => {
    const booking = createInterview({
      candidate: jordan,
      engineer: priya,
      engineers,
      day: "Tue",
      startMinutes: timeToMinutes("14:00"),
      durationMinutes: 30,
    });

    const sameSlot = matchAt(jordan, "14:00", 30, "Tue", [booking]);
    expect(sameSlot.candidateLocked).toBe(true);
    expect(sameSlot.bookable).toBe(false);
    expect(sameSlot.locked).toBe(true);

    const laterSlot = matchAt(jordan, "15:00", 30, "Tue", [booking]);
    expect(laterSlot.bookable).toBe(true);
  });

  it("locks the booked engineer for other candidates without blocking a free teammate", () => {
    const booking = createInterview({
      candidate: jordan,
      engineer: priya,
      engineers,
      day: "Tue",
      startMinutes: timeToMinutes("14:00"),
      durationMinutes: 30,
    });

    const otherCandidate: Candidate = {
      ...jordan,
      id: "99",
      name: "Avery Kim",
    };

    const slot = matchAt(otherCandidate, "14:00", 30, "Tue", [booking]);
    expect(slot.busyEngineers.map((person) => person.id)).toEqual(["2"]);
    expect(slot.availableEngineers.map((person) => person.id)).toEqual(["3"]);
    expect(slot.bookable).toBe(true);

    const onlyPriya = matchAt(otherCandidate, "14:00", 30, "Tue", [booking], [priya]);
    expect(onlyPriya.bookable).toBe(false);
    expect(onlyPriya.locked).toBe(true);
  });

  it("creates a confirmation payload only when the chosen engineer is free", () => {
    const interview = createInterview({
      candidate: jordan,
      engineer: priya,
      engineers,
      day: "Tue",
      startMinutes: timeToMinutes("14:30"),
      durationMinutes: 30,
    });

    expect(interview.summary).toBe(
      "Priya Shah will interview Jordan Hale on Tuesday from 2:30 PM to 3:00 PM.",
    );
    expect(interview.durationMinutes).toBe(30);

    expect(() =>
      createInterview({
        candidate: jordan,
        engineer: alex,
        engineers,
        day: "Tue",
        startMinutes: timeToMinutes("14:30"),
