import availability from "../data/availability.json";
import { CANDIDATE_USER_IDS, ENGINEER_COLORS, ENGINEER_USER_IDS } from "../data/week";
import type { Candidate, Engineer, TimeRange } from "../types";

type DummyUser = {
  id: number;
  firstName: string;
  lastName: string;
  email: string;
  image: string;
  company?: { title?: string; name?: string; department?: string };
};

type DummyResponse = {
  users: DummyUser[];
};

const USERS_URL = "https://dummyjson.com/users?limit=7&select=id,firstName,lastName,email,image,company";

function roleFor(user: DummyUser, fallback: string): string {
  return user.company?.title || user.company?.department || fallback;
}

export async function loadPeople(): Promise<{ engineers: Engineer[]; candidates: Candidate[] }> {
  const response = await fetch(USERS_URL);
  if (!response.ok) {
    throw new Error(`DummyJSON returned ${response.status}`);
  }

  const payload = (await response.json()) as DummyResponse;
  const users = new Map(payload.users.map((user) => [user.id, user]));

  const engineers = ENGINEER_USER_IDS.map((id, index) => {
    const user = users.get(id);
    if (!user) {
      throw new Error(`DummyJSON did not return engineer user ${id}.`);
    }
    return {
      id: String(id),
      name: `${user.firstName} ${user.lastName}`,
      role: roleFor(user, "Engineer"),
      email: user.email,
      image: user.image,
      color: ENGINEER_COLORS[index],
      availability: availability.engineers[String(id) as keyof typeof availability.engineers] as TimeRange[],
    } satisfies Engineer;
  });

  const candidates = CANDIDATE_USER_IDS.map((id) => {
    const user = users.get(id);
    if (!user) {
      throw new Error(`DummyJSON did not return candidate user ${id}.`);
    }
    return {
      id: String(id),
      name: `${user.firstName} ${user.lastName}`,
      role: roleFor(user, "Candidate"),
      email: user.email,
      image: user.image,
      preferred: availability.candidates[String(id) as keyof typeof availability.candidates] as TimeRange,
    } satisfies Candidate;
  });

  return { engineers, candidates };
}

import { useEffect, useState } from "react";

import { loadPeople } from "../api/loadPeople";
import type { Candidate, Engineer } from "../types";

type PeopleState =
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "ready"; engineers: Engineer[]; candidates: Candidate[] };

export function usePeople() {
  const [state, setState] = useState<PeopleState>({ status: "loading" });
  const [nonce, setNonce] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading" });

    loadPeople()
      .then((people) => {
        if (!cancelled) {
          setState({ status: "ready", ...people });
        }
      })
      .catch((error: unknown) => {
        if (!cancelled) {
          setState({
            status: "error",
            message: error instanceof Error ? error.message : "Could not load people.",
          });
        }
      });

    return () => {
      cancelled = true;
    };
  }, [nonce]);

  return {
    ...state,
    retry: () => setNonce((value) => value + 1),
  };
}

import { useEffect, useMemo, useState } from "react";

import {
  createInterview,
  getSlotMatch,
  listBookableSlots,
} from "../lib/schedule";
import type { Candidate, Day, DurationMinutes, Engineer, Interview } from "../types";

export type EngineerFilter = "all" | string;
export type ViewMode = "all" | "bookable";
export type SelectedSlot = { day: Day; start: number };

export function useScheduler(engineers: Engineer[], candidates: Candidate[]) {
  const [candidateId, setCandidateId] = useState(candidates[0]?.id ?? "");
  const [engineerFilter, setEngineerFilter] = useState<EngineerFilter>("all");
  const [durationMinutes, setDurationMinutes] = useState<DurationMinutes>(30);
  const [viewMode, setViewMode] = useState<ViewMode>("all");
  const [selectedSlot, setSelectedSlot] = useState<SelectedSlot | null>(null);
  const [selectedEngineerId, setSelectedEngineerId] = useState<string | null>(null);
  const [bookings, setBookings] = useState<Interview[]>([]);
  const [error, setError] = useState("");
  const [justBooked, setJustBooked] = useState<Interview | null>(null);

  const candidate = candidates.find((person) => person.id === candidateId) ?? null;
  const visibleEngineers =
    engineerFilter === "all"
      ? engineers
      : engineers.filter((person) => person.id === engineerFilter);

  const bookableSlots = useMemo(
    () =>
      listBookableSlots({
        candidate,
        engineers: visibleEngineers,
        durationMinutes,
        bookings,
      }),
    [candidate, visibleEngineers, durationMinutes, bookings],
  );

  const selectedMatch = selectedSlot
    ? getSlotMatch({
        candidate,
        engineers: visibleEngineers,
        day: selectedSlot.day,
        startMinutes: selectedSlot.start,
        durationMinutes,
        bookings,
      })
    : null;

  useEffect(() => {
    setSelectedSlot(null);
    setSelectedEngineerId(null);
    setError("");
    setJustBooked(null);
  }, [candidateId]);

  useEffect(() => {
    setSelectedSlot(null);
    setSelectedEngineerId(null);
    setError("");
  }, [durationMinutes, engineerFilter]);

  function selectSlot(day: Day, start: number) {
    const match = getSlotMatch({
      candidate,
      engineers: visibleEngineers,
      day,
      startMinutes: start,
      durationMinutes,
      bookings,
    });
    if (!match.bookable) {
      return;
    }
    setJustBooked(null);
    setError("");
    setSelectedSlot({ day, start });
    setSelectedEngineerId(match.availableEngineers[0]?.id ?? null);
  }

  function confirmInterview() {
    const engineer = visibleEngineers.find((person) => person.id === selectedEngineerId) ?? null;
    if (!selectedSlot) {
      return;
    }
    try {
      const interview = createInterview({
        candidate,
        engineer,
        engineers: visibleEngineers,
        day: selectedSlot.day,
        startMinutes: selectedSlot.start,
        durationMinutes,
        bookings,
      });
      setBookings((current) => [...current, interview]);
      setJustBooked(interview);
      setSelectedSlot(null);
      setSelectedEngineerId(null);
      setError("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Could not schedule that interview.");
    }
  }

  return {
    candidate,
    candidateId,
    setCandidateId,
    engineerFilter,
    setEngineerFilter,
    durationMinutes,
    setDurationMinutes,
    viewMode,
    setViewMode,
    selectedSlot,
    selectedEngineerId,
    setSelectedEngineerId,
    selectedMatch,
    bookings,
    bookableSlots,
    visibleEngineers,
    error,
    justBooked,
    selectSlot,
    confirmInterview,
  };
}

