import type { SlotMatch } from "../types";

type SlotCellProps = {
  match: SlotMatch;
  selected: boolean;
  muted: boolean;
  heightClass: string;
  label: string;
  onSelect: () => void;
};

export function SlotCell({ match, selected, muted, heightClass, label, onSelect }: SlotCellProps) {
  const bookedCaption = match.locked
    ? match.candidateLocked
      ? "Booked"
      : "Locked"
    : match.bookable
      ? match.availableEngineers.length === 1
        ? match.availableEngineers[0].name.split(" ")[0]
        : `${match.availableEngineers.length} eng`
      : null;

  const className = [
    "flex items-center justify-between gap-1.5 border border-transparent px-1.5 text-left",
    heightClass,
    match.bookable ? "cursor-pointer border-[#8ec9a8] bg-bookable-bg hover:border-bookable hover:bg-[#c6e8d4]" : "cursor-default",
    match.availableEngineers.length + match.busyEngineers.length > 0 &&
    !match.candidateAvailable &&
    !match.locked
      ? "bg-[repeating-linear-gradient(-45deg,#ece7dc,#ece7dc_5px,#e2ddd2_5px,#e2ddd2_10px)]"
      : "",
    match.candidateAvailable &&
    match.availableEngineers.length === 0 &&
    !match.locked
      ? "border-dashed border-[#e0a078] bg-candidate-bg"
      : "",
    selected ? "border-bookable bg-[#c6e8d4]" : "",
    match.locked ? "cursor-default border-ink bg-ink text-white" : "",
    muted ? "opacity-20" : "",
    !match.bookable ? "bg-[#f3eee4]" : "",
  ]
    .filter(Boolean)
    .join(" ");

  const shownEngineers = match.locked ? match.busyEngineers : match.availableEngineers;

  return (
    <button
      type="button"
      className={className}
      disabled={!match.bookable}
      aria-label={label}
      aria-pressed={selected}
      onClick={onSelect}
    >
      <span className="flex gap-0.5" aria-hidden="true">
        {shownEngineers.map((engineer) => (
          <span
            key={engineer.id}
            className="h-2 w-2 rounded-full"
            style={{ background: match.locked ? "#fff" : engineer.color }}
          />
        ))}
      </span>
      {bookedCaption ? <span className="truncate text-[11px] font-semibold">{bookedCaption}</span> : null}
    </button>
  );
}

import { WEEK_DATES } from "../data/week";
import type { SelectedSlot, ViewMode } from "../hooks/useScheduler";
import {
  DAYS,
  DAY_LABELS,
  buildTimeSlots,
  formatTime12,
  getSlotMatch,
} from "../lib/schedule";
import type { Candidate, DurationMinutes, Engineer, Interview } from "../types";
import { SlotCell } from "./SlotCell";

type CalendarGridProps = {
  candidate: Candidate | null;
  engineers: Engineer[];
  durationMinutes: DurationMinutes;
  bookings: Interview[];
  selectedSlot: SelectedSlot | null;
  viewMode: ViewMode;
  onSelectSlot: (day: (typeof DAYS)[number], start: number) => void;
};

const HEIGHT: Record<DurationMinutes, string> = {
  15: "h-5",
  30: "h-8",
  60: "h-[3.25rem]",
};

export function CalendarGrid({
  candidate,
  engineers,
  durationMinutes,
  bookings,
  selectedSlot,
  viewMode,
  onSelectSlot,
}: CalendarGridProps) {
  const slots = buildTimeSlots(durationMinutes);
  const heightClass = HEIGHT[durationMinutes];

  return (
    <section className="overflow-auto bg-panel p-3" aria-label="Weekly availability calendar">
      <div
        className="grid min-w-[780px] gap-x-1.5 gap-y-0.5"
        style={{ gridTemplateColumns: "4.75rem repeat(5, minmax(7.5rem, 1fr))" }}
      >
        <div className="h-12" />
        {DAYS.map((day) => (
          <div key={day} className="flex flex-col justify-end px-2 pb-2">
            <span className="font-semibold">{DAY_LABELS[day]}</span>
            <small className="text-muted">{WEEK_DATES[day]}</small>
          </div>
        ))}

        {slots.map((slot) => (
          <div key={slot.start} className="contents">
            <div className="flex translate-y-[-3px] justify-end pr-2 pt-0.5 text-[11px] text-muted">
              {formatTime12(slot.start).replace(" ", "\u00a0")}
            </div>
            {DAYS.map((day) => {
              const match = getSlotMatch({
                candidate,
                engineers,
                day,
                startMinutes: slot.start,
                durationMinutes,
                bookings,
              });
              const selected = selectedSlot?.day === day && selectedSlot.start === slot.start;
              const muted = viewMode === "bookable" && !match.bookable && !match.locked;
              const engineerNames = match.availableEngineers.map((person) => person.name).join(", ");
              const label = match.bookable
                ? `${DAY_LABELS[day]} ${formatTime12(slot.start)}–${formatTime12(slot.end)}, overlap with ${engineerNames}. Schedule interview.`
                : match.locked
                  ? `${DAY_LABELS[day]} ${formatTime12(slot.start)}, locked for this session.`
                  : `${DAY_LABELS[day]} ${formatTime12(slot.start)}, not an overlap.`;

              return (
                <SlotCell
                  key={`${day}-${slot.start}`}
                  match={match}
                  selected={selected}
                  muted={muted}
                  heightClass={heightClass}
                  label={label}
                  onSelect={() => onSelectSlot(day, slot.start)}
                />
              );
            })}
          </div>
        ))}
      </div>
    </section>
  );
}

