          durationMinutes={scheduler.durationMinutes}
          onDurationChange={scheduler.setDurationMinutes}
          viewMode={scheduler.viewMode}
          onViewMode={scheduler.setViewMode}
        />
        <div className="grid grid-cols-[320px_minmax(0,1fr)] items-start gap-0 max-[980px]:grid-cols-1">
          <aside className="flex flex-col gap-3 border-r border-line p-4 max-[980px]:border-r-0 max-[980px]:border-b">
