        onClick={onConfirm}
        disabled={!engineer}
        className="w-full rounded-lg bg-bookable px-3 py-2.5 font-semibold text-white hover:brightness-105 disabled:opacity-40"
      >
        Confirm interview
      </button>
    </section>
  );
}

import type { Candidate, Engineer } from "../types";
